import json,numpy as np
from run import ROOT
m=np.load(ROOT/'results/model_0.npz');d=np.load(ROOT/'data.npz');data=dict(w=[m[f'arr_{i}'].tolist() for i in range(4)],x=d['x'][d['test'][:30]].tolist(),y=d['y'][d['test'][:30]].tolist(),drop=float(m['dropout']))
html='''<!doctype html><html><meta charset="utf-8"><title>When confidence fails</title><style>body{font:17px system-ui;background:#eff4f8;color:#16324f;max-width:900px;margin:40px auto;padding:20px}h1{font-size:42px;margin-bottom:5px}.panel{background:white;padding:25px;border-radius:16px;margin-top:20px}.layout{display:flex;gap:35px;align-items:center}canvas{image-rendering:pixelated;border-radius:10px}label{display:block;margin:15px 0}button,select{font:inherit;padding:8px;border-radius:7px}#bars{flex:1}.bar{height:17px;background:#2563eb;border-radius:3px;display:inline-block}small{color:#526375}input{width:250px}</style><h1>When confidence fails</h1><p>Can an AI tell when a digit becomes hard to read?</p><div class="panel"><label>Example digit <select id="sample"></select></label><label>Noise strength <input id="noise" type="range" min="0" max=".6" step=".01" value="0"><span id="level"></span></label><label>Prediction method <select id="method"><option value="raw">MC Dropout, 30 passes</option><option value="clean">MC with clean calibration</option><option value="mixed">MC with mixed calibration</option><option value="det">Deterministic network</option></select></label><button id="refresh">Try another noise draw</button><div class="layout"><canvas id="image" width="240" height="240"></canvas><div id="bars"></div></div><p id="status"></p></div><div class="panel"><b>What to notice</b><p>Noise changes the pixels. Dropout repeats the prediction with different hidden units disabled, then averages the probabilities. Calibration adjusts how sharply the probabilities are concentrated.</p><p>A high probability can still accompany a wrong answer. In the measured experiment, clean calibration made strong-noise predictions worse, while mixed calibration only partly reduced that harm.</p><small>This is the real seed-0 checkpoint. Interactive noise draws differ from the fixed research experiment. These probabilities are not guarantees about any individual image. Full evidence is in the accompanying report.</small></div><script>const D=DATA;
const sel=document.querySelector('#sample');D.y.forEach((y,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${i+1}: actual digit ${y}`;sel.append(o)});
let drawSeed=42;function rng(s){return()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function normal(r){return Math.sqrt(-2*Math.log(Math.max(r(),1e-10)))*Math.cos(2*Math.PI*r())}
function predict(x,temp,mc){const r=rng(1000);let p=Array(10).fill(0);const K=mc?30:1;for(let k=0;k<K;k++){let h=D.w[1].map((b,j)=>Math.max(0,b+x.reduce((sum,v,i)=>sum+v*D.w[0][i][j],0)));if(mc)h=h.map(v=>r()>D.drop?v/(1-D.drop):0);let z=D.w[3].map((b,j)=>(b+h.reduce((sum,v,i)=>sum+v*D.w[2][i][j],0))/temp);const max=Math.max(...z);z=z.map(v=>Math.exp(v-max));const den=z.reduce((a,b)=>a+b);z.forEach((v,j)=>p[j]+=v/den/K)}return p}
function render(){let i=+sel.value,s=+document.querySelector('#noise').value,r=rng(drawSeed),x=D.x[i].map(v=>Math.max(0,Math.min(1,v+s*normal(r))));document.querySelector('#level').textContent=s.toFixed(2);let c=document.querySelector('canvas').getContext('2d');x.forEach((v,j)=>{let g=Math.round(v*255);c.fillStyle=`rgb(${g},${g},${g})`;c.fillRect((j%8)*30,Math.floor(j/8)*30,30,30)});let mode=document.querySelector('#method').value;let temp=mode==='clean'?0.7266463609473561:mode==='mixed'?0.8715752489241014:1;let p=predict(x,temp,mode!=='det'),pred=p.indexOf(Math.max(...p));document.querySelector('#bars').innerHTML=p.map((v,j)=>`<div>${j} <span class="bar" style="width:${v*250}px"></span> ${(100*v).toFixed(1)}%</div>`).join('');document.querySelector('#status').textContent=`Actual digit: ${D.y[i]} | Prediction: ${pred} | ${pred===D.y[i]?'Correct':'Incorrect'} | Confidence: ${(100*p[pred]).toFixed(1)}%`}
sel.onchange=render;document.querySelector('#noise').oninput=render;document.querySelector('#method').onchange=render;document.querySelector('#refresh').onclick=()=>{drawSeed++;render()};render();</script></html>'''
(ROOT/'demo.html').write_text(html.replace('DATA',json.dumps(data)))
